def hw_to_sim(hw):
    """서보에서 읽은 배열 16개 -> 시뮬 규약 16개."""
    return np.asarray(hw, dtype=float)[SIM2ARR] - OFFSET

def read_sim_vel_cur(self):
        p, v, cur = self.c.read_pos_vel_cur()
        return hw_to_sim(p), np.asarray(v)[SIM2ARR], np.asarray(cur)[SIM2ARR]

def allegro_to_LEAPhand(joints, teleop = False, zeros = True):
    joints = np.array(joints)
    ret_joints = joints + 3.14159
    if zeros:
        ret_joints[0] = ret_joints[4] = ret_joints[8] = 3.14
    if teleop:
        ret_joints[12] = joints[12] + 0.2 
        ret_joints[14] = joints[14] - 0.2   
    return ret_joints

def LEAPhand_to_allegro(joints, teleop = False, zeros = True):
    joints = np.array(joints)
    ret_joints = joints - 3.14159
    if zeros:
        ret_joints[0] = ret_joints[4] = ret_joints[8] = 0
    if teleop:
        ret_joints[12] = joints[12] - 0.2
        ret_joints[14] = joints[14] + 0.2    
    return ret_joints
